import{_ as t,c as a,o as n,a6 as o}from"./chunks/framework.B5rgnJXo.js";const h=JSON.parse('{"title":"BragJack：一个广告拦截级权限的扩展，劫持了五大浏览器的 AI Agent——Prompt Forcing 为什么比提示注入更可怕","description":"Forever Security 研究员 Gal Weizman 披露 BragJack：仅凭 declarativeNetRequest 这一个广告拦截器最常用的权限，同一份 manifest 劫持了 Chrome Gemini Live、Perplexity Comet、Edge Copilot、Opera Neon、Claude in Chrome 五个浏览器 AI Agent。核心是 DiNneR Serving——DNR 削弱 CSP 头 + 重定向 JS 资源，把代码送进特权上下文；再配合 Prompt Forcing 直接接管 Agent 输入通道。累计赏金约 2 万美元，2 个 CVE。EDR 检测不了用英文写的攻击。","frontmatter":{"title":"BragJack：一个广告拦截级权限的扩展，劫持了五大浏览器的 AI Agent——Prompt Forcing 为什么比提示注入更可怕","date":"2026-09-22T00:00:00.000Z","tags":["security","ai","browser","agent-security","cve"],"keywords":["BragJack","Prompt Forcing","declarativeNetRequest","DNR","GlicJack","CVE-2026-0628","CVE-2026-55945","Gemini Live","Perplexity Comet","Copilot","Claude in Chrome","浏览器 AI Agent 安全"],"category":"security/offensive","description":"Forever Security 研究员 Gal Weizman 披露 BragJack：仅凭 declarativeNetRequest 这一个广告拦截器最常用的权限，同一份 manifest 劫持了 Chrome Gemini Live、Perplexity Comet、Edge Copilot、Opera Neon、Claude in Chrome 五个浏览器 AI Agent。核心是 DiNneR Serving——DNR 削弱 CSP 头 + 重定向 JS 资源，把代码送进特权上下文；再配合 Prompt Forcing 直接接管 Agent 输入通道。累计赏金约 2 万美元，2 个 CVE。EDR 检测不了用英文写的攻击。","author":"PFinal南丞","recommend":true,"head":[["link",{"rel":"canonical","href":"https://friday-go.icu/security/offensive/bragjack-prompt-forcing-browser-ai-agent-hijack-2026"}],["meta",{"property":"og:image","content":"https://friday-go.icu/images/covers/security-offensive.svg"}],["meta",{"name":"twitter:image","content":"https://friday-go.icu/images/covers/security-offensive.svg"}],["meta",{"name":"keywords","content":"BragJack,Prompt Forcing,declarativeNetRequest,DNR,GlicJack,CVE-2026-0628,CVE-2026-55945,Gemini Live,Perplexity Comet,Copilot,Claude in Chrome,浏览器 AI Agent 安全, PFinalClub, Golang教程, Go后端开发, Go微服务, PHP, Python, 技术博客"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"article:published_time","content":"2026-09-22T00:00:00.000Z"}],["meta",{"property":"article:modified_time","content":"2026-09-22T05:43:15.000Z"}],["meta",{"property":"article:author","content":"PFinal南丞"}],["meta",{"property":"article:section","content":"攻防研究"}],["meta",{"property":"article:tag","content":"security"}],["meta",{"property":"article:tag","content":"ai"}],["meta",{"property":"article:tag","content":"browser"}],["meta",{"property":"article:tag","content":"agent-security"}],["meta",{"property":"article:tag","content":"cve"}],["meta",{"name":"citation_title","content":"BragJack：一个广告拦截级权限的扩展，劫持了五大浏览器的 AI Agent——Prompt Forcing 为什么比提示注入更可怕"}],["meta",{"name":"citation_author","content":"PFinal南丞"}],["meta",{"name":"citation_date","content":"2026-09-22"}],["meta",{"name":"citation_online_date","content":"2026-09-22"}],["meta",{"property":"og:title","content":"BragJack：一个广告拦截级权限的扩展，劫持了五大浏览器的 AI Agent——Prompt Forcing 为什么比提示注入更可怕"}],["meta",{"property":"og:description","content":"Forever Security 研究员 Gal Weizman 披露 BragJack：仅凭 declarativeNetRequest 这一个广告拦截器最常用的权限，同一份 manifest 劫持了 Chrome Gemini Live、Perplexity Comet、Edge Copilot、Opera Neon、Claude in Chrome 五个浏览器 AI Agent。核心是 DiNneR Serving——DNR 削弱 CSP 头 + 重定向 JS 资源，把代码送进特权上下文；再配合 Prompt Forcing 直接接管 Agent 输入通道。累计赏金约 2 万美元，2 个 CVE。EDR 检测不了用英文写的攻击。"}],["meta",{"property":"og:url","content":"https://friday-go.icu/security/offensive/bragjack-prompt-forcing-browser-ai-agent-hijack-2026"}],["meta",{"name":"twitter:title","content":"BragJack：一个广告拦截级权限的扩展，劫持了五大浏览器的 AI Agent——Prompt Forcing 为什么比提示注入更可怕"}],["meta",{"name":"twitter:description","content":"Forever Security 研究员 Gal Weizman 披露 BragJack：仅凭 declarativeNetRequest 这一个广告拦截器最常用的权限，同一份 manifest 劫持了 Chrome Gemini Live、Perplexity Comet、Edge Copilot、Opera Neon、Claude in Chrome 五个浏览器 AI Agent。核心是 DiNneR Serving——DNR 削弱 CSP 头 + 重定向 JS 资源，把代码送进特权上下文；再配合 Prompt Forcing 直接接管 Agent 输入通道。累计赏金约 2 万美元，2 个 CVE。EDR 检测不了用英文写的攻击。"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"TechArticle\\",\\"headline\\":\\"BragJack：一个广告拦截级权限的扩展，劫持了五大浏览器的 AI Agent——Prompt Forcing 为什么比提示注入更可怕\\",\\"url\\":\\"https://friday-go.icu/security/offensive/bragjack-prompt-forcing-browser-ai-agent-hijack-2026\\",\\"datePublished\\":\\"2026-09-22T00:00:00.000Z\\",\\"dateModified\\":\\"2026-09-22T05:43:15.000Z\\",\\"wordCount\\":32100,\\"timeRequired\\":\\"PT107M\\",\\"proficiencyLevel\\":\\"Advanced\\",\\"author\\":{\\"@type\\":\\"Person\\",\\"name\\":\\"PFinal南丞\\",\\"url\\":\\"https://friday-go.icu/about\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"PFinalClub\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://friday-go.icu/logo.png\\"}},\\"description\\":\\"Forever Security 研究员 Gal Weizman 披露 BragJack：仅凭 declarativeNetRequest 这一个广告拦截器最常用的权限，同一份 manifest 劫持了 Chrome Gemini Live、Perplexity Comet、Edge Copilot、Opera Neon、Claude in Chrome 五个浏览器 AI Agent。核心是 DiNneR Serving——DNR 削弱 CSP 头 + 重定向 JS 资源，把代码送进特权上下文；再配合 Prompt Forcing 直接接管 Agent 输入通道。累计赏金约 2 万美元，2 个 CVE。EDR 检测不了用英文写的攻击。\\",\\"inLanguage\\":\\"zh-CN\\",\\"mainEntityOfPage\\":{\\"@type\\":\\"WebPage\\",\\"@id\\":\\"https://friday-go.icu/security/offensive/bragjack-prompt-forcing-browser-ai-agent-hijack-2026\\"},\\"keywords\\":[\\"BragJack\\",\\"Prompt Forcing\\",\\"declarativeNetRequest\\",\\"DNR\\",\\"GlicJack\\",\\"CVE-2026-0628\\",\\"CVE-2026-55945\\",\\"Gemini Live\\",\\"Perplexity Comet\\",\\"Copilot\\",\\"Claude in Chrome\\",\\"浏览器 AI Agent 安全\\"],\\"articleSection\\":\\"攻防研究\\"}"],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"首页\\",\\"item\\":{\\"@id\\":\\"https://friday-go.icu\\",\\"@type\\":\\"WebPage\\"}},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"安全\\",\\"item\\":{\\"@id\\":\\"https://friday-go.icu/security\\",\\"@type\\":\\"WebPage\\"}},{\\"@type\\":\\"ListItem\\",\\"position\\":3,\\"name\\":\\"攻防研究\\",\\"item\\":{\\"@id\\":\\"https://friday-go.icu/security/offensive\\",\\"@type\\":\\"WebPage\\"}},{\\"@type\\":\\"ListItem\\",\\"position\\":4,\\"name\\":\\"BragJack：一个广告拦截级权限的扩展，劫持了五大浏览器的 AI Agent——Prompt Forcing 为什么比提示注入更可怕\\",\\"item\\":{\\"@id\\":\\"https://friday-go.icu/security/offensive/bragjack-prompt-forcing-browser-ai-agent-hijack-2026\\",\\"@type\\":\\"Article\\"}}]}"]]},"headers":[],"relativePath":"security/offensive/bragjack-prompt-forcing-browser-ai-agent-hijack-2026.md","filePath":"security/offensive/bragjack-prompt-forcing-browser-ai-agent-hijack-2026.md","lastUpdated":1790055795000}'),i={name:"security/offensive/bragjack-prompt-forcing-browser-ai-agent-hijack-2026.md"};function r(s,e,c,l,p,d){return n(),a("div",{"data-pagefind-body":!0},e[0]||(e[0]=[o(`<blockquote><p>过去两年安全圈都在研究提示注入——把恶意指令藏进网页内容里骗 AI。研究员 Gal Weizman 说他发现了&quot;更糟糕的东西&quot;：根本不用骗 AI，直接接管它的输入通道。</p></blockquote><h1 id="bragjack-一个扩展劫持五大浏览器-ai-agent" tabindex="-1">BragJack：一个扩展劫持五大浏览器 AI Agent <a class="header-anchor" href="#bragjack-一个扩展劫持五大浏览器-ai-agent" aria-label="Permalink to &quot;BragJack：一个扩展劫持五大浏览器 AI Agent&quot;">​</a></h1><h2 id="一、发生了什么" tabindex="-1">一、发生了什么 <a class="header-anchor" href="#一、发生了什么" aria-label="Permalink to &quot;一、发生了什么&quot;">​</a></h2><p>2026 年 9 月 16 日，Forever Security 的 Gal Weizman 发布 BragJack 研究成果：<strong>同一份浏览器扩展 manifest，劫持了五个主流浏览器 AI Agent</strong>——</p><table tabindex="0"><thead><tr><th>目标</th><th>载体</th><th>CVE</th><th>赏金</th><th>状态</th></tr></thead><tbody><tr><td>Chrome Gemini Live</td><td><code>chrome://glic</code> 内嵌 gemini.google.com</td><td>CVE-2026-0628（8.8）</td><td>$7,000</td><td>Chrome 143.0.7499.192/.193 修复（2026-01）</td></tr><tr><td>Perplexity Comet</td><td>内置 agent 扩展</td><td>无 CVE</td><td>$7,000</td><td>已修复</td></tr><tr><td>Edge Copilot (Actions)</td><td>营销页特权 API</td><td>CVE-2026-55945（4.2）</td><td>$5,000</td><td>已修复</td></tr><tr><td>Opera Neon</td><td>内置 agent 扩展</td><td>无 CVE</td><td>$900</td><td>已修复</td></tr><tr><td>Claude in Chrome</td><td>Anthropic 浏览器扩展</td><td>无 CVE</td><td>$600</td><td>已修复（Anthropic 确认为首次报告）</td></tr></tbody></table><p>总赏金约 <strong>20,500 美元</strong>，分配 CVE 的只有两个。五家厂商（Google、Microsoft、Opera、Perplexity、Anthropic）各自独立开发的 Agent，被同一个技术打穿——这不是某家的实现 bug，而是<strong>架构级共同缺陷</strong>。CSA（云安全联盟）的分析把这一点挑明了：这是继 2026 年 3 月 GlicJack 之后，第二次观察到&quot;同一手法泛化到整个 agentic browser 物种&quot;。</p><h2 id="二、前提-agent-的-大脑-身体-模型" tabindex="-1">二、前提：Agent 的&quot;大脑-身体&quot;模型 <a class="header-anchor" href="#二、前提-agent-的-大脑-身体-模型" aria-label="Permalink to &quot;二、前提：Agent 的&quot;大脑-身体&quot;模型&quot;">​</a></h2><p>要理解 BragJack，先要看懂现代浏览器 AI Agent 的架构。Weizman 把它拆成两半：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>文字版架构：浏览器 AI Agent 的信任模型</span></span>
<span class="line"><span>────────────────────────────────────────────────────────</span></span>
<span class="line"><span>  [大脑 Brain]                          [身体 Body]</span></span>
<span class="line"><span>  厂商的 Web 应用                       特权浏览器组件</span></span>
<span class="line"><span>  gemini.google.com                     chrome://glic</span></span>
<span class="line"><span>  perplexity.ai                         内置扩展 (Comet)</span></span>
<span class="line"><span>  claude.ai                             Edge 内部页面</span></span>
<span class="line"><span>       │                                     ▲</span></span>
<span class="line"><span>       │   指令经此通道下发                   │</span></span>
<span class="line"><span>       └─────────────────────────────────────┘</span></span>
<span class="line"><span>             身体无条件信任大脑的指令</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  身体的权限（以用户身份）：</span></span>
<span class="line"><span>  · 读写任意标签页内容      · 截屏</span></span>
<span class="line"><span>  · 打开本地文件 (file://)  · 摄像头 / 麦克风（Chrome）</span></span>
<span class="line"><span>  · 模拟用户操作            · 代发邮件、执行工具调用</span></span>
<span class="line"><span>────────────────────────────────────────────────────────</span></span></code></pre></div><p>关键问题：<strong>身体如何区分&quot;厂商服务器发来的指令&quot;和&quot;其他东西发来的指令&quot;？</strong></p><p>厂商的答案是：只信任来自自家域名的内容。Chrome 阻止扩展向 <code>chrome://glic</code> 注入 content script；Comet 只接受来自 perplexity.ai 域系的消息。<strong>防线全部建在&quot;域名信任&quot;上</strong>。</p><p>而 Weizman 发现的缺口是：控制域名信任的是浏览器网络栈——<strong>而网络栈可以被扩展用 DNR 改写</strong>。</p><h2 id="三、核心技术-dinner-serving" tabindex="-1">三、核心技术：DiNneR Serving <a class="header-anchor" href="#三、核心技术-dinner-serving" aria-label="Permalink to &quot;三、核心技术：DiNneR Serving&quot;">​</a></h2><h3 id="_3-1-dnr-是什么-为什么它是完美载体" tabindex="-1">3.1 DNR 是什么，为什么它是完美载体 <a class="header-anchor" href="#_3-1-dnr-是什么-为什么它是完美载体" aria-label="Permalink to &quot;3.1 DNR 是什么，为什么它是完美载体&quot;">​</a></h3><p><code>declarativeNetRequest</code>（DNR）是 Chrome 84 引入的声明式网络请求 API，设计初衷是替代老的全量监听 API（<code>webRequest</code>），让广告拦截器不必读取请求内容就能改写流量。它的权限请求温和到几乎没人警惕——<strong>每一家广告拦截器都要这个权限</strong>。</p><p>DNR 能做两件事，恰好构成一条注入链：</p><ol><li><strong>改响应头</strong>（<code>modifyHeaders</code>）——可以移除 <code>Content-Security-Policy</code>、<code>X-Frame-Options</code>、<code>cross-origin-embedder-policy</code> 等安全头；</li><li><strong>重定向资源</strong>（<code>redirect</code>）——把页面要加载的 <code>good.com/a.js</code> 改道到 <code>bad.com/b.js</code>。</li></ol><h3 id="_3-2-dinner-serving-三步走" tabindex="-1">3.2 DiNneR Serving 三步走 <a class="header-anchor" href="#_3-2-dinner-serving-三步走" aria-label="Permalink to &quot;3.2 DiNneR Serving 三步走&quot;">​</a></h3><p>Weizman 把&quot;DNR 削弱 + 重定向&quot;的组合技命名为 <strong>DiNneR Serving</strong>，并在原文中称其为一种新颖的 Web 攻击（novel web attack）；他也提到此前曾协助多家厂商修复过同类实例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>文字版攻击链</span></span>
<span class="line"><span>──────────────────────────────────────────────────────</span></span>
<span class="line"><span>[Weaken] DNR 规则：移除目标特权页面的 CSP 等安全头</span></span>
<span class="line"><span>         → 页面处于&quot;无脚本限制&quot;状态</span></span>
<span class="line"><span>[Execute] DNR 规则：劫持页面本来就要加载的一个 JS 资源</span></span>
<span class="line"><span>         → 重定向到攻击者服务器上的 execute.js</span></span>
<span class="line"><span>[Result] 攻击者代码在特权上下文内运行</span></span>
<span class="line"><span>         → 与&quot;身体&quot;（特权 Agent 组件）同源、同上下文</span></span>
<span class="line"><span>         → 直接调用身体暴露的内部 API</span></span>
<span class="line"><span>──────────────────────────────────────────────────────</span></span></code></pre></div><p>厂商防的是&quot;扩展向特权页面注入脚本&quot;（content script blocklist），没防的是&quot;扩展改写特权页面的<strong>网络流量</strong>&quot;。脚本注入被禁，流量改写畅通——<strong>同一枚硬币的两面，只封了一面</strong>。</p><h2 id="四、五个目标-五条路径" tabindex="-1">四、五个目标，五条路径 <a class="header-anchor" href="#四、五个目标-五条路径" aria-label="Permalink to &quot;四、五个目标，五条路径&quot;">​</a></h2><h3 id="_4-1-chrome-gemini-live-glicjack-的泛化起点" tabindex="-1">4.1 Chrome Gemini Live（GlicJack 的泛化起点） <a class="header-anchor" href="#_4-1-chrome-gemini-live-glicjack-的泛化起点" aria-label="Permalink to &quot;4.1 Chrome Gemini Live（GlicJack 的泛化起点）&quot;">​</a></h3><p><strong>架构</strong>：<code>chrome://glic</code> 是特权主体，通过 WebView 嵌入 <code>gemini.google.com</code>（大脑）。Chromium 把内容脚本屏蔽列表做成了域名清单，但 Weizman 发现 Chromium 错误地<strong>允许扩展对 WebView 内的 https 页面应用 DNR 规则</strong>。</p><p><strong>利用</strong>：</p><ul><li>Weaken：DNR 移除 CSP，并把 <code>document-isolation-policy</code> 改为 <code>isolate-and-credentialless</code>（允许跨域脚本与 SharedArrayBuffer 共存）；</li><li>Execute：把页面加载的 <code>https://www.gstatic.com/feedback/js/help/prod/service/lazy.min.js</code> 重定向到攻击者的 <code>execute.js</code>。</li></ul><p><strong>效果</strong>：代码以 gemini.google.com 源运行在 <code>chrome://glic</code> 特权上下文中，可调用 <code>glicBrowserCreateTab</code>、<code>glicBrowserGetContextFromFocusedTab</code> 等内部命令——读任意网站、读 <code>file://</code> 本地文件和 PDF、截屏、读取用户 Profile，Chrome 的媒体能力甚至允许<strong>静默开启摄像头和麦克风</strong>。这就是 CVE-2026-0628 拿到 8.8 分的原因（NVD 描述为 &quot;insufficient policy enforcement in the WebView tag&quot;）。修复（Chromium Issue 463155954，P1/S1）在 2026 年 1 月的 Chrome 143.0.7499.192/.193 落地——Weizman 于 2025 年 11 月 23 日报告，到修复约六周。</p><h3 id="_4-2-perplexity-comet-信任清单里的一颗雷" tabindex="-1">4.2 Perplexity Comet：信任清单里的一颗雷 <a class="header-anchor" href="#_4-2-perplexity-comet-信任清单里的一颗雷" aria-label="Permalink to &quot;4.2 Perplexity Comet：信任清单里的一颗雷&quot;">​</a></h3><p><strong>架构</strong>：Comet 的&quot;身体&quot;是内置扩展，通过 <code>externally_connectable</code> 声明信任域——这个清单里混进了 <code>testing.perplexity.com</code> 这样的测试域名，而测试域唯一的防护是 302 重定向到主域。</p><p><strong>利用</strong>：</p><ul><li>Weaken：DNR 移除 302 响应的 <code>location</code> 头，重定向失效；</li><li>Execute：向 testing 域注入 content script，获得向内置扩展发消息的能力。</li></ul><p><strong>效果</strong>：直接发送 <code>CALL_TOOL</code>（读历史、开标签、截屏）和 <code>START_AGENT</code>（自然语言指挥 Agent 干活）。研究者的 PoC 是让 Agent&quot;总结我最近的邮件并发到攻击者地址&quot;。有个精妙的细节：Comet 曾修过 <code>file://</code> 访问，但只匹配小写——<code>FiLe:///etc/hosts</code> 大小写变体直接绕过。<strong>大小写敏感的协议校验是个老坑，在 Agent 时代复活了</strong>。</p><h3 id="_4-3-edge-copilot-三重绕过-toctou-竞态" tabindex="-1">4.3 Edge Copilot：三重绕过 + TOCTOU 竞态 <a class="header-anchor" href="#_4-3-edge-copilot-三重绕过-toctou-竞态" aria-label="Permalink to &quot;4.3 Edge Copilot：三重绕过 + TOCTOU 竞态&quot;">​</a></h3><p>Edge 的攻击最体现工程功夫，因为它的防线最多：</p><ol><li><strong>CSP 削弱</strong>：Edge 营销页 <code>microsoft.com/en-us/edge</code> 被赋予 <code>edgeMarketingPagePrivate.sendCopilotQuery()</code> 特权 API。DNR 把营销页的 <code>frame-ancestors</code> 放宽为 <code>https://*.com</code>——任意网站都能 iframe 嵌入它；</li><li><strong>手势伪造</strong>：Agent 要求&quot;真实用户手势&quot;。扩展利用 <code>debugger</code> 权限附着到标签页，分发合成点击事件，骗到有效的手势令牌；</li><li><strong>Prompt Forcing 竞态</strong>：Edge 有 Think/Do 双模式（防止&quot;一边被塞指令一边执行&quot;）。攻击时序：<code>enableEdgeTools(false)</code> → 强制填入 prompt（此时动作被禁，可以塞）→ 立刻 <code>enableEdgeTools(true)</code> → Agent 执行前检查设置时看到&quot;已启用&quot;，直接动手。<strong>检查与执行之间的窗口被精确踩点</strong>——教科书级 TOCTOU。</li></ol><p>这是 CVE-2026-55945（4.2 分）。评分争议很大：微软给的是 Medium，但效果是完整的 Agent 接管。PoC 还有个彩蛋——用 <code>bad at gmail.com</code> 绕过 <code>@</code> 符号过滤。</p><h3 id="_4-4-opera-neon-忘了挂锁的门" tabindex="-1">4.4 Opera Neon：忘了挂锁的门 <a class="header-anchor" href="#_4-4-opera-neon-忘了挂锁的门" aria-label="Permalink to &quot;4.4 Opera Neon：忘了挂锁的门&quot;">​</a></h3><p>与 Comet 同构，但更简单：<code>opera.com</code> 域<strong>根本没有阻止 content script 附着</strong>。攻击者在 opera.com 上下文运行代码后直接调用：</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 基于 Forever Security 披露的消息格式改写（变量名已简化）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">chrome.runtime.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sendMessage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(neon, {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  type: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;neon:open&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prompt: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;{攻击者构造的完整提示词}&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // ...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p>配合 DiNneR Serving 去 CSP 后藏在不可见 iframe 里，用户全程无感。赏金 $900——Opera 自称同期独立发现了问题，但依然发了赏金。</p><h3 id="_4-5-claude-in-chrome-dom-属性信任的代价" tabindex="-1">4.5 Claude in Chrome：DOM 属性信任的代价 <a class="header-anchor" href="#_4-5-claude-in-chrome-dom-属性信任的代价" aria-label="Permalink to &quot;4.5 Claude in Chrome：DOM 属性信任的代价&quot;">​</a></h3><p>Claude 的方案与前四者不同——它是普通扩展（不是浏览器内置）。它的 content script 只注入 <code>claude.ai</code>，监听 <code>#claude-onboarding-button</code> 的点击，把元素的 <code>data-task-prompt</code> 属性值转发给侧边栏。</p><p><strong>利用</strong>：其他扩展在 claude.ai 页面上（DiNneR 或 debugger 辅助）设置 <code>document.body.id = &#39;claude-onboarding-button&#39;</code> 和自己的 <code>data-task-prompt</code>，然后合成点击。Body 本身不验证点击的来源与元素完整性。赏金 $600，Anthropic 确认这是该缺陷的首次报告。</p><h2 id="五、prompt-forcing-prompt-injection" tabindex="-1">五、Prompt Forcing ≠ Prompt Injection <a class="header-anchor" href="#五、prompt-forcing-prompt-injection" aria-label="Permalink to &quot;五、Prompt Forcing ≠ Prompt Injection&quot;">​</a></h2><p>这是 BragJack 最值得记录的概念贡献：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│              Prompt Injection（提示注入）                │</span></span>
<span class="line"><span>│  攻击面：AI 正在读取的内容（网页/邮件/文档）             │</span></span>
<span class="line"><span>│  手段：把恶意指令藏在内容里，赌模型分不清谁在说话        │</span></span>
<span class="line"><span>│  对策：护栏、指令分层、工具白名单 —— 有对抗空间          │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│              Prompt Forcing（提示强制）                  │</span></span>
<span class="line"><span>│  攻击面：Agent 的输入通道本身（特权组件的消息接口）      │</span></span>
<span class="line"><span>│  手段：架构漏洞 + 权限滥用，直接把整条 prompt 塞进通道  │</span></span>
<span class="line"><span>│  对策：无 —— 攻击者此刻就是&quot;厂商服务器&quot;                  │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────┘</span></span></code></pre></div><p>三个残酷推论：</p><ol><li><strong>没有恶意代码参与最终动作</strong>。执行攻击的是浏览器自己的合法 Agent，用的是自己的合法高权限，遵循的是一句语法完美的英文。Weizman 的原话：<strong>&quot;EDRs are not built to detect attacks written in plain English.&quot;</strong></li><li><strong>模型护栏完全无关</strong>。你把 Claude/Gemini/Copilot 的安全训练做得再好也没用——恶意指令走的是&quot;厂商指令&quot;通道，在 Agent 眼里它就是正版指令。</li><li><strong>Morphisec 分析师 Brad LaPorte 在 6 月的判断被验证</strong>：AI 驱动的攻击速度超过检测速度——EDR 观察、解读、判定、响应的链条，跟不上&quot;一次合成点击即完成&quot;的攻击。</li></ol><h2 id="六、防御清单" tabindex="-1">六、防御清单 <a class="header-anchor" href="#六、防御清单" aria-label="Permalink to &quot;六、防御清单&quot;">​</a></h2><p>按责任方分层：</p><p><strong>浏览器/Agent 厂商</strong>（真正的根治层）：</p><ol><li>特权上下文（<code>chrome://</code> 页、内部 WebView）必须对扩展的 DNR、content script、debugger <strong>全量免疫</strong>——Chrome 对 glic 的修复就是这个思路；</li><li><code>externally_connectable</code> 白名单最小化，且清单内所有域必须同等防护（Comet 的 testing 域教训）;</li><li>营销页不该持有可触发 Agent 的特权 API（Edge 的 <code>sendCopilotQuery</code> 教训）；</li><li>设置校验与动作执行之间做原子化，消灭 TOCTOU 窗口（Edge 竞态教训）；</li><li>协议 scheme 校验大小写不敏感并标准化（Comet 的 <code>FiLe://</code> 教训）。</li></ol><p><strong>企业 IT</strong>：</p><ol><li>扩展准入清单：<code>declarativeNetRequest</code> + <code>https://*/*</code> + <code>debugger</code> 的组合是高危信号，应纳入扩展审计规则；</li><li>高价值岗位考虑限制未上架商店扩展与开发者模式扩展的安装；</li><li>DLP 对 Agent 代发邮件等动作增加二次确认。</li></ol><p><strong>个人用户</strong>：</p><ol><li>及时更新浏览器（Chrome CVE-2026-0628 已在 143.0.7499.192/.193 修复）；</li><li>审视扩展：一个广告拦截器级别的权限列表，理论上就是 BragJack 的入场券。<strong>装扩展前问一句：我真的需要它吗？</strong></li><li>截至 BragJack 公开时，暂无该技术在野利用的证据——它是责任披露下的研究，但架构缺陷的修复节奏（Comet/Neon/Claude 至今无公开 CVE 与明确修复时间线）提醒我们：同类问题不会一次修完。</li></ol><h2 id="七、写在最后" tabindex="-1">七、写在最后 <a class="header-anchor" href="#七、写在最后" aria-label="Permalink to &quot;七、写在最后&quot;">​</a></h2><p>BragJack 真正可怕的不是 $20,500 赏金或 2 个 CVE，而是它的<strong>泛化性</strong>：五家互相竞争的厂商，在&quot;Agent 如何信任输入&quot;这个核心安全问题上，抄了同一份有缺陷的答卷。CSA 把这称为 agentic browser 的&quot;单一文化&quot;（monoculture）风险——<strong>当整个物种共享同一个信任模型，一个漏洞类就是一个生态级事件</strong>。</p><p>对正在给自家产品装 AI Agent 的开发者，这组案例给出一条铁律：<strong>Agent 的每个输入通道都要当作攻击面对待，不管指令看起来有多&quot;官方&quot;。</strong> 信任域清单里混进一个测试域名、一个营销页特权 API、一次非原子的设置检查，都足够攻击者把你的 Agent 变成他们的 Agent。</p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ol><li>Forever Security · BragJack: Hijacking every browser agent（技术概述）：<a href="https://forever.security/blog/bragjack-attack-hijacks-every-browser-agent" target="_blank" rel="noreferrer">https://forever.security/blog/bragjack-attack-hijacks-every-browser-agent</a></li><li>CSA Labs · Research Note: BragJack agentic browser monoculture：<a href="https://labs.cloudsecurityalliance.org/research/csa-research-note-bragjack-agentic-browser-monoculture-20260" target="_blank" rel="noreferrer">https://labs.cloudsecurityalliance.org/research/csa-research-note-bragjack-agentic-browser-monoculture-20260</a></li><li>NVD — CVE-2026-0628：<a href="https://nvd.nist.gov/vuln/detail/CVE-2026-0628" target="_blank" rel="noreferrer">https://nvd.nist.gov/vuln/detail/CVE-2026-0628</a></li><li>NVD — CVE-2026-55945：<a href="https://nvd.nist.gov/vuln/detail/CVE-2026-55945" target="_blank" rel="noreferrer">https://nvd.nist.gov/vuln/detail/CVE-2026-55945</a></li><li>Chrome Releases（143.0.7499.192 修复公告）：<a href="https://chromereleases.googleblog.com/2026/01/stable-channel-update-for-desktop.html" target="_blank" rel="noreferrer">https://chromereleases.googleblog.com/2026/01/stable-channel-update-for-desktop.html</a></li><li>Tech Times · Single Extension Hijacks AI Agents in Five Browsers（2026-09-20）：<a href="https://www.techtimes.com/articles/327778/20260920/single-extension-hijacks-ai-agents-five-browsers-without-any-user-clicks.htm" target="_blank" rel="noreferrer">https://www.techtimes.com/articles/327778/20260920/single-extension-hijacks-ai-agents-five-browsers-without-any-user-clicks.htm</a></li><li>站内相关：<a href="/ai/claude-code-2-1-271-bash-domain-sandboxing-2026">Claude Code 2.1.271 域级 Bash 沙箱</a> · <a href="/dev/backend/golang/go-mcp-sdk-dns-rebinding-cve-2026-34742-2026">Go MCP SDK DNS rebinding（CVE-2026-34742）</a> · <a href="/ai/mcp-governance-firewall-enterprise-enforcement-2026">MCP 治理面成型</a></li></ol>`,61)]))}const m=t(i,[["render",r]]);export{h as __pageData,m as default};
